// Load institutes.json to build a code → name map for verification
const institutesPath = join(root, "data/processed/2026/institutes.json");
const institutes = JSON.parse(readFileSync(institutesPath, "utf-8"));
const codeToInstitute = new Map(institutes.map(i => [i.code, i]));

// Convert FRA instId to 5-digit CAP code
function toCapCode(instId) {
  const digits = instId.replace(/^EN/, "");
  return digits.padStart(5, "0");
}

// Build the new fees.json
const output = {
  _meta: {
    source: "DTE Maharashtra / FRA (Fee Regulating Authority) approved fee structure 2025-26",
    url: "https://ay26-27.mahafraportal.org/ssi_prp_25/admin/reports/ajax/get_report_ajax.php?district=all&institute=&sub_type=ENGG&type=HT",
    year: "2025-26",
    note: "Fees keyed by 5-digit CAP college code. otherFees = totalAnnualFee - tuitionFee - developmentFee. fraOrderUrl is null (FRA portal does not link individual orders). Amounts are not independently verified against FRA order PDFs.",
    lastUpdated: "2026-09-27",
    totalEntries: FRA_DATA.length,
  }
};

const matchedCodes = [];
const unmatchedIds = [];

for (const row of FRA_DATA) {
  const capCode = toCapCode(row.instId);
  const otherFees = Math.max(0, row.totalFee - row.tuitionFee - row.developmentFee);
  const institute = codeToInstitute.get(capCode);

  if (!institute) {
    unmatchedIds.push(`${row.instId} → ${capCode}: ${row.name}`);
    // Still include in output — feeIndex.ts will try name matching as fallback
  }

  matchedCodes.push(capCode);
  output[capCode] = {
    name: institute ? institute.name : row.name,
    collegeCode: capCode,
    tuitionFee: row.tuitionFee,
    developmentFee: row.developmentFee,
    otherFees,
    totalAnnualFee: row.totalFee,
    tfwsAvailable: false,
    tfwsSeats: null,
    fraOrderRef: null,
    fraOrderUrl: null,
    sampleOnly: false,
  };
}

// Merge legacy entries (for colleges not in FRA portal), FRA entries take precedence
for (const [code, entry] of Object.entries(LEGACY_ENTRIES)) {
  if (!output[code]) {
    output[code] = entry;
  }
}

// Write output
const outPath = join(root, "apps/api/src/data/fees.json");
writeFileSync(outPath, JSON.stringify(output, null, 2) + "\n");

const total = Object.keys(output).filter(k => !k.startsWith("_")).length;
console.log(`Written ${total} entries to fees.json (${matchedCodes.length} from FRA + ${Object.keys(LEGACY_ENTRIES).filter(k => !output[k] || !matchedCodes.includes(k)).length} legacy preserved)`);
console.log(`Matched in institutes.json: ${matchedCodes.length - unmatchedIds.length}`);
console.log(`Unmatched (code not in institutes.json): ${unmatchedIds.length}`);
if (unmatchedIds.length) {
  console.log("Unmatched:");
  unmatchedIds.forEach(id => console.log(" ", id));
}
